Q: Retrieve all Animator States and set them manually in code A: <p>Here is bit of a necroposting, but due to the comments the question is still actual... ;)) I've had a task to check all the animation states from all my game characters at once but through a script, because I didn't want to manage every animator's transitions, loops etc. (about 50 characters). After some investigation and dozens of iterations, the script has been done ;) It's a bit overcomplicated but can be easily adapted to the discussion task.</p>
<pre><code>using System.Collections;
using System.Collections.Generic;
using UnityEditor.Animations;
using UnityEngine;

namespace Test
{
    [RequireComponent(typeof(Animator))]
    public class AnimationsPlayer: MonoBehaviour
    {
        [SerializeField] private float _animationChangeDelay = 1;
        [SerializeField] private float _animationSpeed = 1;
        [SerializeField] private int _animationRepeats = 1;
        [SerializeField] private bool _isLooping = true;
        private AnimatorController _animatorController;
        private Animator _animator;

        private void Awake()
        {
            _animator = GetComponent&lt;Animator&gt;();
        }

        private void Start()
        {
            _animatorController = _animator.runtimeAnimatorController as AnimatorController;
            _animator.speed = _animationSpeed;
            StartCoroutine(PlayAllAnimations(GetAnimationStates(_animatorController), _animationRepeats, _isLooping));
        }

        private List&lt;ChildAnimatorState&gt; GetAnimationStates(AnimatorController controller)
        {
            var childStates = new List&lt;ChildAnimatorState&gt;();
            var animatorControllerLayers = _animatorController.layers;

            foreach (var layer in animatorControllerLayers)
                childStates.AddRange(layer.stateMachine.states);

            return childStates;
        }

        private IEnumerator PlayAllAnimations(List &lt;ChildAnimatorState&gt; states, int animationRepeats, bool isLooping)
        {
            var animationStartTime = 0;
            var stateLayer = -1;
            var animatorStoppedSpeedValue = 0;

            do
            {
                foreach (var state in states)
                {
                    for (var i = 0; i &lt; animationRepeats; i++)
                    {
                        _animator.speed = _animationSpeed;

                        _animator.Play(state.state.name, stateLayer, animationStartTime);

                        yield return new WaitForSeconds(state.state.motion.averageDuration / _animationSpeed);

                        _animator.speed = animatorStoppedSpeedValue;
                    }

                    yield return new WaitForSeconds(_animationChangeDelay);
                }
            } 
            while (isLooping);

            yield return null;
        }
    }
}
</code></pre>
